-- ============================================================================
-- ForestGuro — Migration 0005: hand-authored core question bank
--
-- 180 questions: 6 board subjects x 3 difficulties x 10.
--
-- These are the verified backbone of the bank. Every correct answer here is
-- checkable against Philippine forestry law, a standard mensuration formula, or
-- settled wood science — not inferred. The generated questions produced by
-- scripts/generate-questions.ts are measured against this set.
--
-- Within each subject/difficulty block of 10, the first 4 go to the practice
-- pool and the remaining 6 to mock, mirroring the 2000/3000 target split.
--
-- explanation is deliberately left NULL. The first user to answer a question
-- triggers one OpenAI call, and the result is written back to the row.
--
-- Run AFTER 0004_question_pools.sql. Safe to re-run: re-running updates the
-- question text and options but never overwrites an explanation already
-- generated for a row.
-- ============================================================================

insert into public.questions
  (id, subject, difficulty, pool, question, options, correct_answer_id)
values

