on conflict (id) do update set
  subject           = excluded.subject,
  difficulty        = excluded.difficulty,
  pool              = excluded.pool,
  question          = excluded.question,
  options           = excluded.options,
  correct_answer_id = excluded.correct_answer_id,
  updated_at        = now();
-- explanation is deliberately absent from the update list: re-running this file
-- refreshes wording without discarding an explanation already generated.

-- ----------------------------------------------------------------------------
-- Verification — expect 180 rows, 30 per subject, 60 per difficulty,
-- 72 practice and 108 mock.
-- ----------------------------------------------------------------------------
select pool, difficulty, count(*) as questions
from public.questions
where id ~ '^[a-z]{3}-1[0-3][0-9]$'
group by rollup (pool, difficulty)
order by pool, difficulty;
